mapper.update:
/*updateMasterWmPgPrewarhsngWarhsngReg_GR_QTY*/

		UPDATE KEP_BEFORE_STOCKED_MNG /* 선입고관리 */
		SET GR_QTY = 0 /* 물류센터 입고수량 */
		WHERE 1=1
		AND BUYER = #{BUYER_CODE}
		AND BS_NO = #{BS_NO}

/*updateMasterWmPgPrewarhsngWarhsngReg_IV_QTY*/

		UPDATE KEP_BEFORE_STOCKED_MNG /* 선입고관리 */
		SET IV_QTY = 0 /* 물류센터 출고수량 */
		  , DELIVERY_FLAG = NULL
		WHERE 1=1
		AND BUYER = #{BUYER_CODE}
		AND BS_NO = #{BS_NO}

/*insertMasterWmPgPrewarhsngReleaseReg*/

		DELETE FROM KEP_BEFORE_STOCKED_WMSIVDT
		WHERE SELLER = 'KRKORE0001'
		    AND INV_NO = #{INV_NO}
		    AND INV_SEQ = #{INV_SEQ}
			AND BUYER = #{BUYER_CODE}
		    AND BS_NO = #{BS_NO}

/*updateMasterWmPgPrewarhsngDlvryReg_KEP_BEFORE_STOCKED_MNG*/

		UPDATE KEP_BEFORE_STOCKED_MNG A /* 선입고관리 */
		SET A.CHANGE_DATE = TO_CHAR(SYSDATE,'YYYYMMDD')
		  , A.CHANGE_TIME = TO_CHAR(SYSDATE,'HH24MMSS')
		  , A.DI_QTY = 0
		WHERE 1=1
		AND A.BUYER = #{BUYER_CODE}
		AND A.BS_NO = #{BS_NO}
